    }
}

bool get_apsp_moves(Pos p_from, Pos p_to, std::vector<char>& out_moves) {
    out_moves.clear();
    if (p_from == p_to) return true;
    if (APSP_DIST[p_from.r][p_from.c][p_to.r][p_to.c] == -1) return false; 

    out_moves.reserve(APSP_DIST[p_from.r][p_from.c][p_to.r][p_to.c]);
    Pos curr = p_to;
    while(curr != p_from) {
       Pos prev = APSP_PARENT[p_from.r][p_from.c][curr.r][curr.c];
       out_moves.push_back(get_move_char(prev, curr));
       curr = prev;
    }
    std::reverse(out_moves.begin(), out_moves.end());
    return true;
}

std::vector<std::vector<std::vector<int>>> CELL_VISIT_TIMES_GLOBAL_BUFFER; 

struct CellDirtInfo {
    long double weighted_dirt_contribution;
    Pos p;
    bool operator<(const CellDirtInfo& other) const {
        return weighted_dirt_contribution > other.weighted_dirt_contribution; 
    }
};
std::vector<CellDirtInfo> TMP_CELL_DIRT_INFOS_LIST_GLOBAL_BUFFER; 

struct PathData {
    std::vector<char> moves;
    std::vector<Pos> coords; 
    bool visited_flags[40][40]; 
    long double score_val;
    long double total_dirt_sum_numerator; 
    long double cell_dirt_term_sum[40][40]; 

    PathData() : score_val(1e18L), total_dirt_sum_numerator(0.0L) {
        for(int i=0; i<N_GRID_SIZE; ++i) for(int j=0; j<N_GRID_SIZE; ++j) { 
            visited_flags[i][j] = false;
            cell_dirt_term_sum[i][j] = 0.0L;
        }
    }

    PathData(const PathData& other) = default;
    PathData(PathData&& other) = default;
    PathData& operator=(const PathData& other) = default;
    PathData& operator=(PathData&& other) = default;
};

bool update_coords_and_visited_flags(PathData& pd) {
    pd.coords.assign(1, Pos{0,0}); 
    if (!pd.moves.empty()) { 
      pd.coords.reserve(pd.moves.size() + 1); 
    }

    for (int r = 0; r < N_GRID_SIZE; ++r) for (int c = 0; c < N_GRID_SIZE; ++c) pd.visited_flags[r][c] = false;
    pd.visited_flags[0][0] = true;

    Pos current_p = Pos{0,0};
    for (char move_char : pd.moves) {
        int dir_idx = -1;
        for (int i = 0; i < 4; ++i) if (DIR_CHARS[i] == move_char) dir_idx = i;

        if (dir_idx == -1) return false; 

        Pos next_p = Pos{(int16_t)(current_p.r + DR[dir_idx]), (int16_t)(current_p.c + DC[dir_idx])};
        if (!is_valid_pos(next_p.r, next_p.c) || check_wall(current_p, next_p)) return false; 

        current_p = next_p;
        pd.coords.push_back(current_p);
        pd.visited_flags[current_p.r][current_p.c] = true;
    }
    return true;
}

void calculate_score_full(PathData& pd) {
    if (!update_coords_and_visited_flags(pd)) {
        pd.score_val = 1e18L; 
        return;
    }

    if (pd.moves.size() > MAX_L_PATH) {
        pd.score_val = 1e18L; return;
    }
    if (!pd.moves.empty()){ 
        if (pd.coords.back() != Pos{0,0}) { pd.score_val = 1e18L; return;}
    } else { 
        if (N_GRID_SIZE > 1) { 
             pd.score_val = 1e18L; return;
        }
    }

    for (int r = 0; r < N_GRID_SIZE; ++r) for (int c = 0; c < N_GRID_SIZE; ++c) {
        if (!pd.visited_flags[r][c]) { pd.score_val = 1e18L; return; }
    }

    int L = pd.moves.size();

    if (L == 0) { 
       pd.score_val = (N_GRID_SIZE == 1) ? 0.0L : 1e18L; // N=1 case not in this contest
       pd.total_dirt_sum_numerator = 0;
       if (N_GRID_SIZE == 1) pd.cell_dirt_term_sum[0][0] = 0;
       return;
    }

    for(int r=0; r<N_GRID_SIZE; ++r) {
        for(int c=0; c<N_GRID_SIZE; ++c) {
            CELL_VISIT_TIMES_GLOBAL_BUFFER[r][c].clear(); 
        }
    }

    for (int t = 1; t <= L; ++t) { 
        Pos p = pd.coords[t]; 
        CELL_VISIT_TIMES_GLOBAL_BUFFER[p.r][p.c].push_back(t);
    }

    pd.total_dirt_sum_numerator = 0;

    for (int r_ = 0; r_ < N_GRID_SIZE; ++r_) {
        for (int c_ = 0; c_ < N_GRID_SIZE; ++c_) {
            const auto& specific_cell_visits = CELL_VISIT_TIMES_GLOBAL_BUFFER[r_][c_];
            long double current_cell_dirt_term = 0; 

            if (!specific_cell_visits.empty()){
                 int num_visits_in_cycle = specific_cell_visits.size();
                 for (int i = 0; i < num_visits_in_cycle; ++i) {
                    long long prev_visit_t = (i == 0) ? ((long long)specific_cell_visits[num_visits_in_cycle - 1] - L) : (long long)specific_cell_visits[i-1];
                    long long cur_visit_t = specific_cell_visits[i];
                    long long delta = cur_visit_t - prev_visit_t; 
                    current_cell_dirt_term += (long double)delta * (delta - 1) / 2.0L;
                }
            } else { 
                current_cell_dirt_term = (long double)L * (L - 1) / 2.0L;
            }
            pd.cell_dirt_term_sum[r_][c_] = current_cell_dirt_term;
            pd.total_dirt_sum_numerator += (long double)D_SUSC[r_][c_] * current_cell_dirt_term;
        }
    }
    pd.score_val = pd.total_dirt_sum_numerator / L;
}

bool initial_dfs_visited[40][40]; 

void calculate_score_full(PathData& pd);

void generate_initial_dfs_path(int r, int c, PathData& pd) {
    // Build three susceptibility-threshold macrocycles and keep the best exact-scored route.
    using MoveList = std::vector<char>;

    auto append_shortest = [&](MoveList& route, Pos from, Pos to) -> bool {
        if (APSP_DIST[from.r][from.c][to.r][to.c] < 0) return false;

        Pos cur = to;
        MoveList reversed;
        reversed.reserve(APSP_DIST[from.r][from.c][to.r][to.c]);

        while (cur != from) {
            Pos prev = APSP_PARENT[from.r][from.c][cur.r][cur.c];
            reversed.push_back(get_move_char(prev, cur));
            cur = prev;
        }

        route.insert(route.end(), reversed.rbegin(), reversed.rend());
        return true;
    };

    auto build_macrocycle = [&](int percentile) -> MoveList {
        MoveList route;

        std::vector<int> sorted_values;
        sorted_values.reserve(N_GRID_SIZE * N_GRID_SIZE);
        for (int i = 0; i < N_GRID_SIZE; ++i)
            for (int j = 0; j < N_GRID_SIZE; ++j)
                sorted_values.push_back(D_SUSC[i][j]);

        std::sort(sorted_values.begin(), sorted_values.end());
        int threshold =
            sorted_values[(sorted_values.size() - 1) * percentile / 100];
        int median_value = sorted_values[sorted_values.size() / 2];

        // Mandatory coverage backbone over the whole reachable board.
        bool covered[40][40] = {};
        std::function<void(Pos)> cover = [&](Pos u) {
            covered[u.r][u.c] = true;

            for (int dir = 0; dir < 4; ++dir) {
                Pos v{(int16_t)(u.r + DR[dir]),
                      (int16_t)(u.c + DC[dir])};

                if (!is_valid_pos(v.r, v.c) ||
                    covered[v.r][v.c] ||
                    check_wall(u, v))
                    continue;

                route.push_back(DIR_CHARS[dir]);
                cover(v);
                route.push_back(DIR_CHARS[(dir + 2) % 4]);
            }
        };
        cover(Pos{0, 0});

        bool component_used[40][40] = {};
        std::vector<Pos> anchors;
        std::vector<int> component_sums;
        std::vector<MoveList> patrols;

        // Extract hot connected components and construct one closed patrol per component.
        for (int sr = 0; sr < N_GRID_SIZE; ++sr) {
            for (int sc = 0; sc < N_GRID_SIZE; ++sc) {
                if (component_used[sr][sc] ||
                    D_SUSC[sr][sc] < threshold)
                    continue;

                std::vector<Pos> component;
                std::vector<Pos> queue;
                queue.push_back(Pos{(int16_t)sr, (int16_t)sc});
                component_used[sr][sc] = true;

                for (size_t head = 0; head < queue.size(); ++head) {
                    Pos u = queue[head];
                    component.push_back(u);

                    for (int dir = 0; dir < 4; ++dir) {
                        Pos v{(int16_t)(u.r + DR[dir]),
                              (int16_t)(u.c + DC[dir])};

                        if (!is_valid_pos(v.r, v.c) ||
                            component_used[v.r][v.c] ||
                            D_SUSC[v.r][v.c] < threshold ||
                            check_wall(u, v))
                            continue;

                        component_used[v.r][v.c] = true;
                        queue.push_back(v);
                    }
                }

                Pos anchor = component.front();
                int component_sum = 0;
                for (Pos u : component) {
                    component_sum += D_SUSC[u.r][u.c];
                    if (D_SUSC[u.r][u.c] > D_SUSC[anchor.r][anchor.c])
                        anchor = u;
                }

                MoveList patrol;
                bool local_used[40][40] = {};

                // Iterative DFS creates an Euler-style closed walk of the
                // component spanning tree, beginning and ending at anchor.
                struct Frame {
                    Pos position;
                    int next_direction;
                };

                std::vector<Frame> stack;
                stack.push_back({anchor, 0});
                local_used[anchor.r][anchor.c] = true;

                while (!stack.empty()) {
                    Frame& frame = stack.back();
                    bool descended = false;

                    while (frame.next_direction < 4) {
                        int dir = frame.next_direction++;
                        Pos u = frame.position;
                        Pos v{(int16_t)(u.r + DR[dir]),
                              (int16_t)(u.c + DC[dir])};

                        if (!is_valid_pos(v.r, v.c) ||
                            local_used[v.r][v.c] ||
                            D_SUSC[v.r][v.c] < threshold ||
                            check_wall(u, v))
                            continue;

                        local_used[v.r][v.c] = true;
                        patrol.push_back(DIR_CHARS[dir]);
                        stack.push_back({v, 0});
                        descended = true;
                        break;
                    }

                    if (descended) continue;

                    Pos finished = frame.position;
                    stack.pop_back();

                    if (!stack.empty()) {
                        Pos parent = stack.back().position;
                        int back_direction = 0;
                        while (parent.r + DR[back_direction] != finished.r ||
                               parent.c + DC[back_direction] != finished.c)
                            ++back_direction;

                        patrol.push_back(
                            DIR_CHARS[(back_direction + 2) % 4]);
                    }
                }

                anchors.push_back(anchor);
                component_sums.push_back(component_sum);
                patrols.push_back(std::move(patrol));
            }
        }

        // Visit anchors in nearest-neighbor order from the origin.
        std::vector<int> order(anchors.size());
        std::iota(order.begin(), order.end(), 0);

        Pos current{0, 0};
        for (size_t out = 0; out < order.size(); ++out) {
            size_t best = out;
            int best_distance =
                APSP_DIST[current.r][current.c]
                         [anchors[order[best]].r][anchors[order[best]].c];

            for (size_t k = out + 1; k < order.size(); ++k) {
                int distance =
                    APSP_DIST[current.r][current.c]
                             [anchors[order[k]].r][anchors[order[k]].c];

                if (distance >= 0 &&
                    (best_distance < 0 || distance < best_distance)) {
                    best = k;
                    best_distance = distance;
                }
            }

            std::swap(order[out], order[best]);
            int component_id = order[out];
            Pos anchor = anchors[component_id];

            if (!append_shortest(route, current, anchor))
                continue;

            const int denominator =
                std::max(1, median_value * 8);
            int repeats =
                1 + component_sums[component_id] / denominator;
            repeats = std::min(repeats, 8);

            for (int rep = 0; rep < repeats; ++rep) {
                if (route.size() + patrols[component_id].size() >
                    MAX_L_PATH)
                    break;

                route.insert(route.end(),
                             patrols[component_id].begin(),
                             patrols[component_id].end());
            }

            current = anchor;
        }

        append_shortest(route, current, Pos{0, 0});
        return route;
    };

    // Compare exactly the requested three deterministic susceptibility cuts.
    PathData constructed_best;
    constructed_best.score_val = 1e18L;

    for (int percentile : {35, 60, 82}) {
        PathData candidate;
        candidate.moves = build_macrocycle(percentile);

        if (candidate.moves.size() > MAX_L_PATH)
            continue;

        calculate_score_full(candidate);
        if (candidate.score_val < constructed_best.score_val)
            constructed_best = std::move(candidate);
    }

    if (constructed_best.score_val < 1e17L)
        pd = std::move(constructed_best);
    else {
        // Preserve the original legal DFS fallback if every macrocycle
        // exceeds the output limit.
        initial_dfs_visited[r][c] = true;
        for (int dir_idx = 0; dir_idx < 4; ++dir_idx) {
            Pos current_p{(int16_t)r, (int16_t)c};
            Pos next_p{(int16_t)(r + DR[dir_idx]),
                       (int16_t)(c + DC[dir_idx])};

            if (is_valid_pos(next_p.r, next_p.c) &&
                !check_wall(current_p, next_p) &&
                !initial_dfs_visited[next_p.r][next_p.c]) {
                pd.moves.push_back(DIR_CHARS[dir_idx]);
                generate_initial_dfs_path(next_p.r, next_p.c, pd);
                pd.moves.push_back(DIR_CHARS[(dir_idx + 2) % 4]);
            }
        }
    }
}

Pos select_target_cell_for_dirt_ops(const PathData& current_pd_obj, bool use_sqrt_N_sampling) {
    TMP_CELL_DIRT_INFOS_LIST_GLOBAL_BUFFER.clear(); 
    if (current_pd_obj.score_val > 1e17L) { 
        std::uniform_int_distribution<int> r_dist(0, N_GRID_SIZE-1);
        return Pos{(int16_t)r_dist(RND_ENGINE), (int16_t)r_dist(RND_ENGINE)};
    }

    for(int r=0; r<N_GRID_SIZE; ++r) {
        for(int c=0; c<N_GRID_SIZE; ++c) {
             TMP_CELL_DIRT_INFOS_LIST_GLOBAL_BUFFER.push_back({(long double)D_SUSC[r][c] * current_pd_obj.cell_dirt_term_sum[r][c], Pos{(int16_t)r,(int16_t)c}});
        }
    }
    std::sort(TMP_CELL_DIRT_INFOS_LIST_GLOBAL_BUFFER.begin(), TMP_CELL_DIRT_INFOS_LIST_GLOBAL_BUFFER.end());

    if (TMP_CELL_DIRT_INFOS_LIST_GLOBAL_BUFFER.empty()) { 
        std::uniform_int_distribution<int> r_dist(0, N_GRID_SIZE-1);
        return Pos{(int16_t)r_dist(RND_ENGINE), (int16_t)r_dist(RND_ENGINE)};
    }

    int K_select;
    if(use_sqrt_N_sampling){ 
        K_select = std::min((int)TMP_CELL_DIRT_INFOS_LIST_GLOBAL_BUFFER.size(), std::max(1, N_GRID_SIZE));
    } else { 
        K_select = std::min((int)TMP_CELL_DIRT_INFOS_LIST_GLOBAL_BUFFER.size(), std::max(10, N_GRID_SIZE * N_GRID_SIZE / 10));
    }

    if (K_select <= 0) { 
         std::uniform_int_distribution<int> r_dist(0, N_GRID_SIZE-1);
         return Pos{(int16_t)r_dist(RND_ENGINE), (int16_t)r_dist(RND_ENGINE)};
    }

    std::uniform_int_distribution<int> top_k_dist(0, K_select - 1);
    return TMP_CELL_DIRT_INFOS_LIST_GLOBAL_BUFFER[top_k_dist(RND_ENGINE)].p;
}

const int OP4_SAMPLE_POINTS = 20; 
const int OP5_MAX_SUBSEGMENT_LEN = 20; 

std::vector<char> GET_APSP_MOVES_BUFFER1;
std::vector<char> GET_APSP_MOVES_BUFFER2;

/**
 * Build four bounded global service schedules.
 *
 * Each schedule repeatedly selects the most urgent cell according to its
 * dirt susceptibility and estimated age, divided by travel cost.  During the
 * initial coverage phase every unvisited cell is prioritized.  APSP paths are
 * appended directly, and the resulting closed route is scored exactly.
 */
PathData generate_service_schedule_seed() {
    PathData best;
    best.score_val = 1e18L;

    const double exponents[4] = {1.5, 1.8, 2.1, 2.4};
    const int cells = N_GRID_SIZE * N_GRID_SIZE;

    for (int start_id = 0; start_id < 4; ++start_id) {
        std::vector<char> route;
        route.reserve(50000);
        std::vector<int> last_visit(cells, 0);
        std::vector<unsigned char> seen(cells, 0);

        Pos current{0, 0};
        int elapsed = 0;
        int covered = 1;
        seen[0] = 1;

        // The initial age estimate favors cells that are far from the origin.
        for (int r = 0; r < N_GRID_SIZE; ++r) {
            for (int c = 0; c < N_GRID_SIZE; ++c) {
                int id = r * N_GRID_SIZE + c;
                last_visit[id] = -2 * APSP_DIST[0][0][r][c] - 1;
            }
        }
        last_visit[0] = 0;

        for (int waypoint = 0; waypoint < 5000; ++waypoint) {
            Pos target{-1, -1};
            double best_value = -1.0;

            // Complete coverage is mandatory, so unvisited cells override
            // the ordinary urgency score.
            if (covered < cells) {
                for (int r = 0; r < N_GRID_SIZE; ++r) {
                    for (int c = 0; c < N_GRID_SIZE; ++c) {
                        int id = r * N_GRID_SIZE + c;
                        if (seen[id]) continue;
                        int dist = APSP_DIST[current.r][current.c][r][c];
                        if (dist < 0) continue;
                        double value = static_cast<double>(D_SUSC[r][c]) /
                                       (1.0 + dist);
                        if (target.r < 0 || value > best_value) {
                            best_value = value;
                            target = Pos{(int16_t)r, (int16_t)c};
                        }
                    }
                }
            } else {
                for (int r = 0; r < N_GRID_SIZE; ++r) {
                    for (int c = 0; c < N_GRID_SIZE; ++c) {
                        int dist = APSP_DIST[current.r][current.c][r][c];
                        if (dist < 0) continue;
                        int id = r * N_GRID_SIZE + c;
                        double age = std::max(1, elapsed - last_visit[id]);
                        double predicted = age + dist + 1.0;
                        double value =
                            static_cast<double>(D_SUSC[r][c]) *
                            std::pow(predicted, exponents[start_id]) /
                            std::max(1, dist);
                        if (target.r < 0 || value > best_value) {
                            best_value = value;
                            target = Pos{(int16_t)r, (int16_t)c};
                        }
                    }
                }
            }

            if (target.r < 0) break;
            if (!get_apsp_moves(current, target, GET_APSP_MOVES_BUFFER1))
                break;

            if (route.size() + GET_APSP_MOVES_BUFFER1.size() > 50000)
                break;

            for (char move : GET_APSP_MOVES_BUFFER1) route.push_back(move);

            Pos walk = current;
            last_visit[walk.r * N_GRID_SIZE + walk.c] = elapsed;
            for (char move : GET_APSP_MOVES_BUFFER1) {
                int dir = 0;
                while (DIR_CHARS[dir] != move) ++dir;
                walk.r += DR[dir];
                walk.c += DC[dir];
                ++elapsed;
                int id = walk.r * N_GRID_SIZE + walk.c;
                if (!seen[id]) {
                    seen[id] = 1;
                    ++covered;
                }
                last_visit[id] = elapsed;
            }
            current = target;
        }

        if (covered != cells) continue;
        if (!get_apsp_moves(current, Pos{0, 0}, GET_APSP_MOVES_BUFFER1))
            continue;
        if (route.size() + GET_APSP_MOVES_BUFFER1.size() > MAX_L_PATH)
            continue;
        route.insert(route.end(), GET_APSP_MOVES_BUFFER1.begin(),
                     GET_APSP_MOVES_BUFFER1.end());

        PathData candidate;
        candidate.moves = std::move(route);
        calculate_score_full(candidate);
        if (candidate.score_val < best.score_val)
            best = std::move(candidate);
    }

    return best;
}


int main(int argc, char *argv[]) {
    std::ios_base::sync_with_stdio(false); std::cin.tie(NULL);

    double time_limit_seconds = 1.95; 
    if (argc > 1) time_limit_seconds = std::stod(argv[1]);

    auto time_start_prog = std::chrono::high_resolution_clock::now();
    RND_ENGINE.seed(std::chrono::system_clock::now().time_since_epoch().count());

    std::cin >> N_GRID_SIZE;
    H_WALLS_INFO.resize(N_GRID_SIZE - 1); 
    V_WALLS_INFO.resize(N_GRID_SIZE);     

    for (int i = 0; i < N_GRID_SIZE - 1; ++i) std::cin >> H_WALLS_INFO[i];
    for (int i = 0; i < N_GRID_SIZE; ++i) std::cin >> V_WALLS_INFO[i]; 
    for (int i = 0; i < N_GRID_SIZE; ++i) for (int j = 0; j < N_GRID_SIZE; ++j) std::cin >> D_SUSC[i][j];

    MAX_L_PATH_HIGH_THRESHOLD_EFFECTIVE = MAX_L_PATH * 0.95; 
    MIN_L_PATH_LOW_THRESHOLD_EFFECTIVE = N_GRID_SIZE * N_GRID_SIZE; 

    compute_apsp();

    CELL_VISIT_TIMES_GLOBAL_BUFFER.resize(N_GRID_SIZE);
    TMP_CELL_DIRT_INFOS_LIST_GLOBAL_BUFFER.reserve(N_GRID_SIZE * N_GRID_SIZE);
    for(int r=0; r<N_GRID_SIZE; ++r) {
        CELL_VISIT_TIMES_GLOBAL_BUFFER[r].resize(N_GRID_SIZE);
        int reserve_size = std::max(2, MAX_L_PATH / (N_GRID_SIZE*N_GRID_SIZE) + 50);
         if (reserve_size > MAX_L_PATH / 2 && MAX_L_PATH > 2) reserve_size = MAX_L_PATH/2; // Cap reasonable max
        for(int c=0; c<N_GRID_SIZE; ++c) {
             CELL_VISIT_TIMES_GLOBAL_BUFFER[r][c].reserve(reserve_size);
        }
    }
    GET_APSP_MOVES_BUFFER1.reserve(N_GRID_SIZE*N_GRID_SIZE*2); 
    GET_APSP_MOVES_BUFFER2.reserve(N_GRID_SIZE*N_GRID_SIZE*2);


    PathData current_pd_obj;
    for(int i=0; i<N_GRID_SIZE; ++i) for(int j=0; j<N_GRID_SIZE; ++j) initial_dfs_visited[i][j] = false;
    PathData service_seed = generate_service_schedule_seed();
    if (service_seed.score_val < 1e17L) {
        current_pd_obj = std::move(service_seed);
    } else {
        generate_initial_dfs_path(0, 0, current_pd_obj);
        calculate_score_full(current_pd_obj);
    }

    PathData best_pd_obj = current_pd_obj;

    double start_temp = 5000.0 * sqrt(N_GRID_SIZE); 
    double end_temp = 0.1;    

    int iterations_count = 0;
    PathData candidate_pd_obj; 
    std::uniform_real_distribution<double> accept_dist_01(0.0, 1.0);


    while(true) {
        iterations_count++;
        if(iterations_count % 100 == 0){ 
            auto now_time = std::chrono::high_resolution_clock::now();
            double elapsed_seconds = std::chrono::duration<double>(now_time - time_start_prog).count();
            if (elapsed_seconds > time_limit_seconds) break;
        }

        int L_curr = current_pd_obj.moves.size();

